<?php
require_once '../../includes/auth_check.php';
requireAdmin();
require_once '../../config/database.php';
$status_filter = $_GET['status'] ?? '';
$search = trim($_GET['search'] ?? '');
$where = ['1=1'];
if (in_array($status_filter, ['pending','dikonfirmasi','dalam_perjalanan','selesai','dibatalkan'], true)) $where[] = "j.status='" . $conn->real_escape_string($status_filter) . "'";
if ($search) { $safeSearch = $conn->real_escape_string($search); $where[] = "(j.kode_jemput LIKE '%$safeSearch%' OR u.nama LIKE '%$safeSearch%' OR u.no_hp LIKE '%$safeSearch%')"; }
$list = $conn->query("SELECT j.*, u.nama, u.email FROM everwear_jemput j JOIN users u ON u.id=j.customer_id WHERE " . implode(' AND ', $where) . " ORDER BY FIELD(j.status,'pending','dikonfirmasi','dalam_perjalanan','selesai','dibatalkan'), j.created_at DESC");
$status_badge = ['pending'=>['orange','Menunggu Konfirmasi'],'dikonfirmasi'=>['blue','Dikonfirmasi'],'dalam_perjalanan'=>['blue','Dijemput'],'selesai'=>['green','Selesai'],'dibatalkan'=>['red','Dibatalkan']];
$summary = [];
foreach (['pending','dikonfirmasi','dalam_perjalanan','selesai','dibatalkan'] as $status) {
    $result = $conn->query("SELECT COUNT(*) AS c FROM everwear_jemput WHERE status = '$status'");
    $summary[$status] = intval($result->fetch_assoc()['c']);
}
?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jemput Pakaian — Admin Everwear</title><link rel="stylesheet" href="../../assets/css/output.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head><body><div class="layout"><?php include '../../includes/sidebar_admin_everwear.php'; ?><main class="main"><div class="topbar"><div class="topbar-left"><button class="hamburger" onclick="toggleSidebar()"><i class="fa-solid fa-bars"></i></button><div><h1>Jemput Pakaian</h1><p>Konfirmasi, tandai dijemput, lalu verifikasi dan timbang</p></div></div></div><div class="content"><div class="stats-grid stats-5" style="margin-bottom:1.5rem"><div class="stat-card"><div class="stat-icon orange"><i class="fa-solid fa-clock"></i></div><div class="stat-info"><div class="stat-value"><?=$summary['pending']?></div><div class="stat-label">Menunggu</div></div></div><div class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-circle-check"></i></div><div class="stat-info"><div class="stat-value"><?=$summary['dikonfirmasi']?></div><div class="stat-label">Dikonfirmasi</div></div></div><div class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-truck"></i></div><div class="stat-info"><div class="stat-value"><?=$summary['dalam_perjalanan']?></div><div class="stat-label">Dijemput</div></div></div><div class="stat-card"><div class="stat-icon green"><i class="fa-solid fa-check-double"></i></div><div class="stat-info"><div class="stat-value"><?=$summary['selesai']?></div><div class="stat-label">Selesai</div></div></div><div class="stat-card"><div class="stat-icon red"><i class="fa-solid fa-ban"></i></div><div class="stat-info"><div class="stat-value"><?=$summary['dibatalkan']?></div><div class="stat-label">Dibatalkan</div></div></div></div><div class="card mb-2"><div class="filter-search-wrap"><div class="filter-tabs"><a href="?" class="filter-tab <?=$status_filter===''?'active':''?>">Semua <span class="tab-count"><?=array_sum($summary)?></span></a><a href="?status=pending" class="filter-tab <?=$status_filter==='pending'?'active':''?>">Menunggu <span class="tab-count"><?=$summary['pending']?></span></a><a href="?status=dikonfirmasi" class="filter-tab <?=$status_filter==='dikonfirmasi'?'active':''?>">Dikonfirmasi <span class="tab-count"><?=$summary['dikonfirmasi']?></span></a><a href="?status=dalam_perjalanan" class="filter-tab <?=$status_filter==='dalam_perjalanan'?'active':''?>">Dijemput <span class="tab-count"><?=$summary['dalam_perjalanan']?></span></a><a href="?status=selesai" class="filter-tab <?=$status_filter==='selesai'?'active':''?>">Selesai <span class="tab-count"><?=$summary['selesai']?></span></a><a href="?status=dibatalkan" class="filter-tab <?=$status_filter==='dibatalkan'?'active':''?>">Batal <span class="tab-count"><?=$summary['dibatalkan']?></span></a></div><form method="GET" class="search-form-inline"><input type="hidden" name="status" value="<?=htmlspecialchars($status_filter)?>"><div class="search-bar"><i class="fa-solid fa-magnifying-glass"></i><input name="search" value="<?=htmlspecialchars($search)?>" placeholder="Cari kode, nama, no. HP..."><button class="btn btn-primary btn-sm" type="submit">Cari</button></div></form></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Customer</th><th>Jumlah</th><th>Jadwal</th><th>Alamat</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php while($r=$list->fetch_assoc()): [$bc,$bt]=$status_badge[$r['status']]??['gray',$r['status']]; ?><tr><td><span class="badge badge-blue"><?=htmlspecialchars($r['kode_jemput'])?></span></td><td><strong><?=htmlspecialchars($r['nama'])?></strong><br><small><?=htmlspecialchars($r['email'])?></small></td><td>1. Layak: <?=intval($r['pcs_layak'])?> pcs<br>2. Recycle: <?=intval($r['pcs_recycle'])?> pcs<br><?=number_format($r['berat_kg'],2)?> kg</td><td><?=date('d M Y',strtotime($r['tanggal_jemput']))?><br><?=date('H:i',strtotime($r['jam_jemput']))?></td><td><?=htmlspecialchars($r['alamat_penjemputan'])?></td><td><span class="badge badge-<?=$bc?>"><?=$bt?></span></td><td><?php if($r['status']==='pending'): ?><button class="btn btn-primary btn-sm" onclick="tanyaAksi(<?=$r['id']?>,'konfirmasi','Konfirmasi permintaan ini?')">Konfirmasi</button> <button class="btn btn-danger btn-sm" onclick="tanyaAksi(<?=$r['id']?>,'batalkan','Batalkan permintaan ini?')">Batal</button><?php elseif($r['status']==='dikonfirmasi'): ?><button class="btn btn-primary btn-sm" onclick="tanyaAksi(<?=$r['id']?>,'dijemput','Pakaian akan dijemput sekarang?')">Tandai Dijemput</button><?php elseif($r['status']==='dalam_perjalanan'): ?><button class="btn btn-primary btn-sm" onclick="bukaVerifikasi(<?=$r['id']?>,<?=$r['pcs_layak']?>,<?=$r['pcs_recycle']?>,<?=$r['berat_kg']?>,'<?=htmlspecialchars($r['kode_jemput'],ENT_QUOTES)?>')">Verifikasi & Timbang</button><?php else: ?><button class="btn btn-info btn-sm" onclick="lihatDetail(<?=$r['id']?>)"><i class="fa-solid fa-eye"></i> Detail Permintaan</button><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div></div></div></main></div><div class="modal-overlay" id="modalDetail"><div class="modal" style="max-width:520px"><div class="modal-header"><h3><i class="fa-solid fa-truck" style="color:var(--primary)"></i> Detail Permintaan</h3><button class="modal-close" onclick="tutupDetail()"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body" id="detailContent"></div></div></div><div class="modal-overlay" id="modal"><div class="modal" style="max-width:520px"><div class="modal-header"><h3><i class="fa-solid fa-weight-scale" style="color:var(--primary)"></i> Verifikasi & Timbang</h3><button class="modal-close" onclick="tutup()"><i class="fa-solid fa-xmark"></i></button></div><div class="modal-body"><input type="hidden" id="id"><div id="kodeInfo" style="background:var(--primary-light);padding:.75rem;border-radius:10px;margin-bottom:1rem"></div><div class="form-group"><label class="form-label">Layak Pakai (pcs)</label><input class="form-control" id="layak" type="number" min="0" oninput="previewPoin()"></div><div class="form-group"><label class="form-label">Tidak Layak/Recycle (pcs)</label><input class="form-control" id="recycle" type="number" min="0" oninput="previewPoin()"></div><div class="form-group"><label class="form-label">Berat Aktual (kg)</label><input class="form-control" id="berat" type="number" min="0.1" step="0.1" oninput="previewPoin()"><div class="text-muted text-small">Poin (layak & recycle): 10 poin/kg</div></div><div style="background:var(--primary-light);padding:1rem;border-radius:10px;text-align:center"><div class="text-muted text-small">Poin yang akan diberikan</div><strong id="preview" style="font-size:1.4rem;color:var(--primary-dark)">0 poin</strong></div><div class="form-group" style="margin-top:1rem"><label class="form-label">Catatan Admin (opsional)</label><textarea class="form-control" id="catatan" rows="2"></textarea></div></div><div class="modal-footer"><button class="btn btn-ghost" onclick="tutup()">Batal</button><button class="btn btn-primary" onclick="verifikasi()"><i class="fa-solid fa-check"></i> Verifikasi Selesai</button></div></div></div><script>function toggleSidebar(){document.getElementById('sidebar').classList.toggle('open');document.getElementById('sidebarOverlay').classList.toggle('open')}function closeSidebar(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebarOverlay').classList.remove('open')}function tanyaAksi(id,action,title){Swal.fire({title,text:title,icon:'question',showCancelButton:true,confirmButtonText:'Ya, lanjut',cancelButtonText:'Tidak',confirmButtonColor:'#4CAF50',cancelButtonColor:'#aaa'}).then(r=>{if(r.isConfirmed)aksi(id,action)})}function aksi(id,action){fetch('<?=BASE_URL?>/api/verifikasi-everwear-jemput.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action})}).then(r=>r.json()).then(r=>r.success?Swal.fire('Berhasil',action==='konfirmasi'?'Permintaan dikonfirmasi.':'Pakaian ditandai sudah dijemput.','success').then(()=>location.reload()):Swal.fire('Gagal',r.message,'error')).catch(e=>Swal.fire('Gagal',e.message,'error'))}function lihatDetail(id){document.getElementById('modalDetail').classList.add('open');document.getElementById('detailContent').innerHTML='<div class="empty-state"><i class="fa-solid fa-spinner fa-spin"></i></div>';fetch('<?=BASE_URL?>/api/detail-everwear-jemput.php?id='+id).then(r=>r.json()).then(r=>{if(!r.success)return Swal.fire('Gagal',r.message,'error');const d=r.data;document.getElementById('detailContent').innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:.65rem"><div style="background:var(--bg-light);border-radius:10px;padding:.75rem"><div class="text-muted text-small">Kode</div><strong>${d.kode}</strong></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem"><div class="text-muted text-small">Status</div><strong>${d.status==='pending'?'Menunggu Konfirmasi':(d.status==='dikonfirmasi'?'Dikonfirmasi':(d.status==='dalam_perjalanan'?'Dijemput':(d.status==='selesai'?'Selesai':'Dibatalkan')))}</strong></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem"><div class="text-muted text-small">Customer</div><strong>${d.customer}</strong><br><span class="text-muted text-small">${d.no_hp}</span></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem"><div class="text-muted text-small">Jadwal Jemput</div><strong>${d.jadwal} WIB</strong></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Jumlah Pakaian</div><strong>1. Baju layak: ${d.pcs_layak} pcs<br>2. Recycle: ${d.pcs_recycle} pcs<br>Berat: ${d.berat_kg} kg</strong></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Jarak / Ongkir</div><strong>${d.jarak_km} km (Rp ${d.biaya_ongkir})</strong></div><div style="background:var(--bg-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Alamat Penjemputan</div><div>${d.alamat}</div></div>${d.catatan_lokasi?`<div style="background:var(--accent-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Catatan Lokasi</div><div>${d.catatan_lokasi}</div></div>`:''}${d.catatan_admin?`<div style="background:var(--primary-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Catatan Admin</div><div>${d.catatan_admin}</div></div>`:''}${d.dicatat?`<div style="background:var(--bg-light);border-radius:10px;padding:.75rem;grid-column:1/-1"><div class="text-muted text-small">Dicatat</div><div>${d.dicatat}</div></div>`:''}${d.status==='selesai'?`<div style="background:var(--primary-light);border-radius:10px;padding:.875rem;grid-column:1/-1;text-align:center"><div class="text-muted text-small">Poin Dikreditkan</div><strong style="font-size:1.5rem;color:var(--primary-dark)">+${d.poin_diperoleh} poin</strong></div>`:''}</div>`}).catch(e=>Swal.fire('Gagal',e.message,'error'))}function tutupDetail(){document.getElementById('modalDetail').classList.remove('open')}function bukaVerifikasi(id,layak,recycle,berat,kode){document.getElementById('id').value=id;document.getElementById('layak').value=layak;document.getElementById('recycle').value=recycle;document.getElementById('berat').value=berat;document.getElementById('kodeInfo').textContent='Kode jemput: '+kode;document.getElementById('catatan').value='';previewPoin();document.getElementById('modal').classList.add('open')}function previewPoin(){document.getElementById('preview').textContent=Math.max(1,Math.round(parseFloat(document.getElementById('berat').value||0)*10))+' poin'}function tutup(){document.getElementById('modal').classList.remove('open')}function verifikasi(){const id=+document.getElementById('id').value,pcs_layak=+document.getElementById('layak').value||0,pcs_recycle=+document.getElementById('recycle').value||0,berat_kg=+document.getElementById('berat').value||0,catatan_admin=document.getElementById('catatan').value.trim();if((pcs_layak===0&&pcs_recycle===0)||berat_kg<=0)return Swal.fire('Data belum lengkap','','warning');fetch('<?=BASE_URL?>/api/verifikasi-everwear-jemput.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action:'verifikasi',pcs_layak,pcs_recycle,berat_kg,catatan_admin})}).then(r=>r.json()).then(r=>r.success?Swal.fire('Berhasil','+'+r.poin+' poin diberikan','success').then(()=>location.reload()):Swal.fire('Gagal',r.message,'error')).catch(e=>Swal.fire('Gagal',e.message,'error'))}</script></body></html>